# 41i_mediation_test.R
# Mediation test: Professionalisation → Trust → Turbulence
#
# Direct path:   Professionalisation → Turbulence
# Indirect path:  Professionalisation → Trust → Turbulence
#
# Method: Baron & Kenny (1986) three regressions + Imai, Keele & Tingley
# (2010) mediation package for simulation-based indirect effect CIs.
#
# NOTE: N = 47 full sample / 24 BSA-observed (1979-2025). Interpret as
# suggestive path model, not causal identification. Both series time-trended.
#
# READS (corrected 5 Sep 2026 — this list was stale, still naming the two
# files repointed away from on 2-3 Sep; see fixes below and in the code):
#   ../composite_canonical/canonical_pc1_1979_2025.csv (turbulence DV)
#   data/processed/trust_extended_1979_2025.csv (trust mediator)
#   Rebuilds professionalisation PC1 inline (same construction as 41e-41g,
#   also fixed 5 Sep for the same wrong-Henn-tribble bug — see 41e's header)
#
# OUTPUTS:
#   figures/ch3_mediation_talk.png
#   Console: Baron & Kenny steps, mediation results

if (!require("pacman")) install.packages("pacman")
pacman::p_load(ggplot2, readr, tibble, mediation, dplyr)
select <- dplyr::select  # force dplyr::select over MASS::select

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT <- .ROOT
OUT     <- file.path(PROJECT, "figures/ch3_mediation_talk.png")

NAVY <- "#1F3864"; RED <- "#d7191c"; GREY <- "#607D8B"

# ============================================================
# 1. REBUILD PROFESSIONALISATION PC1 (same as 41e-41g)
# ============================================================
norm01 <- function(x) (x - min(x, na.rm=TRUE)) / (max(x, na.rm=TRUE) - min(x, na.rm=TRUE))
YEARS  <- 1979:2025

career_obs <- bind_rows(
  tribble(~year,~pct, 1979,3.0, 1983,4.5, 2010,14.0, 2015,17.0, 2019,21.0),
  tribble(~year,~pct, 1987,5.4, 1992,7.3, 1997,9.5, 2001,10.5, 2005,14.1)
) |> arrange(year)

career_annual <- tibble(year = YEARS) |>
  mutate(obs_yr     = sapply(year, function(y) max(career_obs$year[career_obs$year <= y])),
         career_pct = career_obs$pct[match(obs_yr, career_obs$year)])

spads <- read_csv(file.path(PROJECT, "data/raw/spads_DATA_ENTRY.csv"),
                  show_col_types = FALSE) |> filter(year <= 2025)
spads_annual <- tibble(year = YEARS,
  n_spads = approx(spads$year, spads$n_spads, xout = YEARS, rule = 2)$y)

ipsa  <- read_csv(file.path(PROJECT,"data/processed/ipsa_staffing_annual.csv"),
                  show_col_types=FALSE) |> select(cal_year, staffing_real=mean_staffing_real_2015)
# REPOINTED 7 Sep 2026: Butler & Butler-calibrated real series, see 41m_staffing_calibrate_butler.R
pre10 <- read_csv(file.path(PROJECT,"data/processed/staffing_pre2010_calibrated_butler.csv"),
                  show_col_types=FALSE) |> filter(!is.na(real_2015_mean)) |>
  select(cal_year=year, staffing_real=real_2015_mean)
staffing_obs <- bind_rows(pre10, ipsa) |> arrange(cal_year) |> filter(cal_year <= 2025)
staffing_annual <- tibble(year = YEARS) |>
  mutate(obs_yr        = sapply(year, function(y) max(staffing_obs$cal_year[staffing_obs$cal_year <= y])),
         staffing_real = staffing_obs$staffing_real[match(obs_yr, staffing_obs$cal_year)])

d_prof <- tibble(year = YEARS) |>
  left_join(career_annual   |> select(year, career_pct),    by="year") |>
  left_join(spads_annual    |> select(year, n_spads),        by="year") |>
  left_join(staffing_annual |> select(year, staffing_real),  by="year") |>
  mutate(career_norm   = norm01(career_pct),
         spads_norm    = norm01(n_spads),
         staffing_norm = norm01(staffing_real))

pca_res <- prcomp(d_prof |> select(career_norm, spads_norm, staffing_norm),
                  scale. = TRUE, center = TRUE)
d_prof  <- d_prof |> mutate(prof_pc1 = pca_res$x[, 1])

# ============================================================
# 2. LOAD TRUST AND TURBULENCE
# ============================================================
trust <- read_csv(file.path(PROJECT, "data/processed/trust_extended_1979_2025.csv"),
                  show_col_types = FALSE) |>
  select(year, trust_pct, data_source) |>
  mutate(observed = !grepl("INTERPOLATED", data_source, fixed = TRUE))
# repointed 3 Sep 2026: was reading trust_v2.csv (BSA-only, 1986-2023) — now
# reads the extended 1979-2025 series (TrustGov/Ipsos-calibrated gap years).
# This script runs BOTH specs (full sample incl. calibrated years, and
# BSA-observed-only) side by side rather than picking one, because 41g found
# the two diverge sharply (full-sample prof->trust r=-0.17 to -0.36 vs
# observed-only r=-0.73 to -0.78) — that divergence has not been adjudicated
# by PJ, so the mediation test should not silently inherit one answer.

turb <- read_csv(file.path(PROJECT, "../composite_canonical/canonical_pc1_1979_2025.csv"),
                 show_col_types = FALSE) |>
  select(year, turb_pc1 = PC1_index)
# repointed 2 Sep 2026: was reading a stale local turbulence_pca.csv (2005-2023,
# 5-component pm_churn spec) — now reads the canonical composite (1979-2025,
# 6-component exec_instab spec). See wkbd-composite-stale-canonical memory.
# NOTE: trust_pct itself still only covers 1986-2024 (BSA) — this repoint fixes
# the DV's own truncation but the mediation sample is still capped by trust
# coverage, not by turbulence coverage, until the trust gap is separately closed.

# ============================================================
# 3. MERGE — all three on overlapping years
# ============================================================
d_all <- turb |>
  inner_join(trust, by = "year") |>
  inner_join(d_prof |> select(year, prof_pc1), by = "year") |>
  filter(!is.na(trust_pct), !is.na(turb_pc1), !is.na(prof_pc1))

cat(sprintf("Mediation dataset (full, incl. calibrated trust years): N = %d, years %d-%d\n",
            nrow(d_all), min(d_all$year), max(d_all$year)))
cat(sprintf("  of which BSA-observed: %d\n", sum(d_all$observed)))
cat("Variables: prof_pc1 (IV), trust_pct (mediator), turb_pc1 (DV)\n\n")

# ============================================================
# 4-6. RUN THE FULL BARON & KENNY + MEDIATION PIPELINE, PARAMETERISED
#      BY DATASET — run once on the full sample, once on BSA-observed-only,
#      since 41g found these diverge sharply and that hasn't been adjudicated.
# ============================================================
run_mediation_pipeline <- function(d, label, out_path) {
  cat(sprintf("\n\n########## SPEC: %s (N = %d, years %d-%d) ##########\n",
              label, nrow(d), min(d$year), max(d$year)))

  eq_total <- lm(turb_pc1 ~ prof_pc1, data = d)
  cat("=== Step 1: Total effect (c) — Prof → Turbulence ===\n")
  cat(sprintf("  b = %.3f, SE = %.3f, p = %.4f, R² = %.3f\n",
              coef(eq_total)["prof_pc1"],
              summary(eq_total)$coefficients["prof_pc1", "Std. Error"],
              summary(eq_total)$coefficients["prof_pc1", "Pr(>|t|)"],
              summary(eq_total)$r.squared))

  eq_a <- lm(trust_pct ~ prof_pc1, data = d)
  cat("\n=== Step 2: Path a — Prof → Trust ===\n")
  cat(sprintf("  b = %.3f, SE = %.3f, p = %.4f, R² = %.3f\n",
              coef(eq_a)["prof_pc1"],
              summary(eq_a)$coefficients["prof_pc1", "Std. Error"],
              summary(eq_a)$coefficients["prof_pc1", "Pr(>|t|)"],
              summary(eq_a)$r.squared))

  eq_full <- lm(turb_pc1 ~ prof_pc1 + trust_pct, data = d)
  cat("\n=== Step 3: Full model — Prof + Trust → Turbulence ===\n")
  print(summary(eq_full))

  c_prime <- coef(eq_full)["prof_pc1"]
  b_path  <- coef(eq_full)["trust_pct"]
  a_path  <- coef(eq_a)["prof_pc1"]
  indirect <- a_path * b_path
  total    <- coef(eq_total)["prof_pc1"]
  prop_med <- indirect / total

  cat(sprintf("\n=== Path summary ===\n"))
  cat(sprintf("  Total effect (c):    %.3f\n", total))
  cat(sprintf("  Direct effect (c'):  %.3f\n", c_prime))
  cat(sprintf("  Path a (Prof→Trust): %.3f\n", a_path))
  cat(sprintf("  Path b (Trust→Turb): %.3f\n", b_path))
  cat(sprintf("  Indirect (a × b):    %.3f\n", indirect))
  cat(sprintf("  Proportion mediated: %.1f%%\n", prop_med * 100))

  cat("\n=== Mediation package: simulation-based indirect effect ===\n")
  set.seed(42)
  med_out <- mediate(eq_a, eq_full,
                     treat = "prof_pc1", mediator = "trust_pct",
                     sims = 5000)
  print(summary(med_out))

  make_path_diagram(d, label, out_path, eq_total, eq_a, eq_full, med_out,
                     c_prime, b_path, a_path, total)

  invisible(list(d = d, label = label, eq_total = eq_total, eq_a = eq_a,
                  eq_full = eq_full, med_out = med_out))
}

# ============================================================
# PATH DIAGRAM WITH ESTIMATED COEFFICIENTS (function, called per spec)
# ============================================================
make_path_diagram <- function(d, spec_label, OUT, eq_total, eq_a, eq_full, med_out,
                               c_prime, b_path, a_path, total) {

# Format coefficient labels
fmt_coef <- function(b, p) {
  stars <- if (p < 0.001) "***" else if (p < 0.01) "**" else if (p < 0.05) "*" else ""
  sprintf("%.2f%s", b, stars)
}

a_label <- fmt_coef(a_path, summary(eq_a)$coefficients["prof_pc1", "Pr(>|t|)"])
b_label <- fmt_coef(b_path, summary(eq_full)$coefficients["trust_pct", "Pr(>|t|)"])
c_label <- fmt_coef(total, summary(eq_total)$coefficients["prof_pc1", "Pr(>|t|)"])
cp_label <- fmt_coef(c_prime, summary(eq_full)$coefficients["prof_pc1", "Pr(>|t|)"])

# Mediation CI
acme_lo <- med_out$d0.ci[1]
acme_hi <- med_out$d0.ci[2]
acme_p  <- med_out$d0.p

indirect_label <- sprintf("Indirect: %.2f [%.2f, %.2f]%s",
                          med_out$d0, acme_lo, acme_hi,
                          if (acme_p < 0.05) "*" else "")

box_w <- 2.5; box_h <- 1.4

p_path <- ggplot() +
  theme_void(base_size = 12) +
  theme(
    plot.background = element_rect(fill = "white", colour = NA),
    plot.margin     = margin(15, 20, 15, 20),
    plot.title      = element_text(face = "bold", colour = NAVY, size = 13, hjust = 0.5),
    plot.subtitle   = element_text(colour = GREY, size = 9, hjust = 0.5, lineheight = 1.3),
    plot.caption    = element_text(colour = GREY, size = 7.5, hjust = 0.5)
  ) +
  coord_fixed(xlim = c(-1.5, 11.5), ylim = c(-1.0, 8.0), expand = FALSE) +
  labs(
    title    = "Mediation test: professionalisation, trust, and turbulence",
    subtitle = sprintf("Spec: %s. N = %d (overlap years %d\u2013%d). Contemporaneous OLS. Health warning: small N, time-trended series.",
                       spec_label, nrow(d), min(d$year), max(d$year)),
    caption  = sprintf("Indirect effect (a \u00d7 b): %.3f, 95%% CI [%.3f, %.3f], p = %.3f (5,000 simulations, Imai et al. 2010).",
                       med_out$d0, acme_lo, acme_hi, acme_p)
  )

# Arrows
p_path <- p_path +
  # Direct path c' (bottom, thick navy)
  annotate("segment", x = 1.5 + box_w/2, y = 2.0,
           xend = 8.5 - box_w/2, yend = 2.0,
           colour = NAVY, linewidth = 2.0,
           arrow = arrow(length = unit(0.35, "cm"), type = "closed")) +
  # Path a: Prof → Trust (dashed, light grey — n.s.)
  annotate("segment", x = 1.5 + box_w/2, y = 2.0 + box_h/2,
           xend = 5.0 - box_w/2, yend = 6.0 - box_h/2,
           colour = "#BBBBBB", linewidth = 1.0, linetype = "dashed",
           arrow = arrow(length = unit(0.25, "cm"), type = "closed")) +
  # Path b: Trust → Turbulence (dashed, light grey — n.s.)
  annotate("segment", x = 5.0 + box_w/2, y = 6.0 - box_h/2,
           xend = 8.5 - box_w/2, yend = 2.0 + box_h/2,
           colour = "#BBBBBB", linewidth = 1.0, linetype = "dashed",
           arrow = arrow(length = unit(0.25, "cm"), type = "closed"))

# Coefficient labels on arrows
p_path <- p_path +
  # c' on direct path
  annotate("label", x = 5.0, y = 1.4,
           label = paste0("c\u2032 = ", cp_label),
           colour = NAVY, fill = "white", size = 4.5, fontface = "bold",
           label.size = 0) +
  # Total effect below
  annotate("text", x = 5.0, y = 0.6,
           label = paste0("(Total c = ", c_label, ")"),
           colour = NAVY, size = 3.5, fontface = "italic") +
  # a on Prof → Trust
  annotate("label", x = 2.7, y = 4.5,
           label = paste0("a = ", a_label),
           colour = GREY, fill = "white", size = 4, fontface = "bold",
           label.size = 0) +
  # b on Trust → Turb
  annotate("label", x = 7.3, y = 4.5,
           label = paste0("b = ", b_label),
           colour = GREY, fill = "white", size = 4, fontface = "bold",
           label.size = 0)

# Indirect effect summary
p_path <- p_path +
  annotate("label", x = 5.0, y = 7.5,
           label = indirect_label,
           colour = GREY, fill = "#f0f0f0", size = 3.5, fontface = "bold",
           label.size = 0.3, label.padding = unit(0.4, "lines"))

# Node boxes
nodes <- data.frame(
  x     = c(1.5, 5.0, 8.5),
  y     = c(2.0, 6.0, 2.0),
  label = c("Professionalisation\nIndex", "Political\nTrust", "Turbulence\nIndex"),
  fill  = c(NAVY, GREY, RED)
)
for (i in 1:nrow(nodes)) {
  p_path <- p_path +
    annotate("rect",
             xmin = nodes$x[i] - box_w/2, xmax = nodes$x[i] + box_w/2,
             ymin = nodes$y[i] - box_h/2, ymax = nodes$y[i] + box_h/2,
             fill = nodes$fill[i], colour = "white", linewidth = 0.8) +
    annotate("text", x = nodes$x[i], y = nodes$y[i],
             label = nodes$label[i],
             colour = "white", fontface = "bold", size = 4.0,
             hjust = 0.5, vjust = 0.5, lineheight = 1.0)
}

ggsave(OUT, p_path, width = 9, height = 6.5, dpi = 300)
cat("\nPath diagram saved:", OUT, "\n")
}

# ============================================================
# 7. RUN BOTH SPECS
# ============================================================
res_full <- run_mediation_pipeline(
  d_all, "Full sample (incl. TrustGov/Ipsos-calibrated years)",
  file.path(PROJECT, "figures/ch3_mediation_talk.png")
)

d_obs <- d_all |> filter(observed)
res_obs <- run_mediation_pipeline(
