)

cat("\n\n########## SPEC COMPARISON ##########\n")
cat(sprintf("Full sample:    N=%d, path a (Prof->Trust) b=%.3f p=%.4f, ACME=%.3f [%.3f, %.3f] p=%.3f\n",
            nrow(res_full$d), coef(res_full$eq_a)["prof_pc1"],
            summary(res_full$eq_a)$coefficients["prof_pc1","Pr(>|t|)"],
            res_full$med_out$d0, res_full$med_out$d0.ci[1], res_full$med_out$d0.ci[2], res_full$med_out$d0.p))
cat(sprintf("BSA-observed:   N=%d, path a (Prof->Trust) b=%.3f p=%.4f, ACME=%.3f [%.3f, %.3f] p=%.3f\n",
            nrow(res_obs$d), coef(res_obs$eq_a)["prof_pc1"],
            summary(res_obs$eq_a)$coefficients["prof_pc1","Pr(>|t|)"],
            res_obs$med_out$d0, res_obs$med_out$d0.ci[1], res_obs$med_out$d0.ci[2], res_obs$med_out$d0.p))
